let historyCache=null,historyRequest=null,companyRange='MAX';
const companyMetricDetails={cap:['Market capitalization','The market value of a company’s outstanding equity.'],revenue:['Revenue','Reported sales from the source financials.'],earnings:['Earnings','Pretax earnings reported by the source; this is not net income.'],price:['Share price','Historical traded prices from Zerodha for the matched NSE/BSE equity listing.'],pe:['P/E ratio','Share valuation relative to reported earnings.'],ps:['Price / sales','Market value relative to revenue.'],pb:['Price / book','Market value relative to book equity.'],margin:['Operating margin','Operating earnings as a percentage of revenue.'],dividend:['Dividend yield','Dividend income as a percentage of the share price.'],employees:['Employees','Employee count from the source company reporting period.'],eps:['Earnings per share','Reported earnings per share.'],assets:['Total assets','Assets on the reported balance sheet.'],netAssets:['Net assets','Reported assets less liabilities.'],liabilities:['Total liabilities','Liabilities on the reported balance sheet.'],debt:['Total debt','Reported company borrowings.'],cash:['Cash on hand','Reported cash and cash equivalents.'],shares:['Shares outstanding','Number of outstanding shares.'],borrow:['Cost to borrow','Reported cost of borrowing shares.']};
function companyURL(s,k){return '#stock/'+encodeURIComponent(s.ticker)+'/'+k}
function companyRank(s){if(s.cap==null||s.isin===null)return null;return stocks.filter(x=>x.cap!=null&&x.isin!==null).sort((a,b)=>b.cap-a.cap).findIndex(x=>x.ticker===s.ticker)+1}
function renderStockPage(s,key){if(!companyMetricDetails[key]&&key!=='reports')key='cap';detailMetric=key;document.title=s.name+' — '+(companyMetricDetails[key]?.[0]||'Reports')+' | IndiaStockView';const rank=companyRank(s),e=escapeHtml;
const primary=['price','cap','revenue','earnings','pe','margin','dividend'];
$('#content').innerHTML=`<div class="stock-breadcrumb"><a href="#rankings">← All companies</a><span>/</span><span>India</span><span>/</span><b>${e(s.name)}</b></div><section class="stock-profile"><div class="stock-identity">${logo(s)}<div><h1>${e(s.name)}</h1><div class="stock-subtitle"><span class="ticker-label">${e(stockTickerLabel(s))}</span><span>🇮🇳 India</span><span class="sector-tag">${e(s.sector||'Unclassified')}</span></div></div></div><div class="stock-actions"><button id="stock-watch" class="${watch.has(s.ticker)?'selected':''}">${watch.has(s.ticker)?'★ Watching':'☆ Watchlist'}</button><button id="stock-compare">⇄ Compare</button></div></section><div class="stock-overview"><div><small>Market cap</small><strong>${metricValue(s,'cap')}</strong><span>${rank?'#'+rank+' among companies with data':s.isin===null?'Current listing identity unverified':'Awaiting financial data'}</span></div><div><small>Share price</small><strong>${stockPrice(s)}</strong><span>${s.referenceValuation?'Share price':feedMode==='kite'?'Zerodha · '+(s.liveSource||'exchange')+' quote':s.eodQuote?s.eodQuote.exchange+' · official close':feedMode==='live'?'INR · exchange quote':/\.(NS|BO)$/.test(s.ticker)?(currency==='INR'?'INR converted · USD source':'USD · source quote'):(currency==='INR'?'INR converted · ADR source':'USD · ADR / overseas quote')}</span></div><div><small>Change · 1 day</small><strong>${changeBadge(s)}</strong><span>${s.change==null?'No quote available':'Signed daily movement'}</span></div><div><small>Revenue</small><strong>${amount(s.revenue,'revenue')}</strong><span>Reported financials</span></div><div><small>P/E ratio</small><strong>${amount(s.pe,'pe')}</strong><span>${s.pe==null?'Not available':'Reported valuation'}</span></div><div><small>Dividend yield</small><strong>${amount(s.dividend,'dividend')}</strong><span>${s.dividend==null?'Not available':'Reported dividend yield'}</span></div></div><nav class="stock-tabs" aria-label="Company metrics">${primary.map(k=>`<a href="${companyURL(s,k)}" class="${key===k?'active':''}" ${key===k?'aria-current="page"':''}>${k==='cap'?'Market cap':k==='price'?'Price history':metrics[k]}</a>`).join('')}<select id="stock-more" aria-label="More company metrics"><option value="">More metrics</option>${Object.keys(companyMetricDetails).filter(k=>!primary.includes(k)&&!['borrow','price'].includes(k)).map(k=>`<option value="${k}" ${key===k?'selected':''}>${companyMetricDetails[k][0]}</option>`).join('')}</select><a href="${companyURL(s,'reports')}" class="${key==='reports'?'active':''}" ${key==='reports'?'aria-current="page"':''}>Reports ↗</a></nav><div class="stock-columns"><div id="stock-main"></div><aside class="stock-sidebar"><section class="card"><div class="eyebrow">COMPANY DETAILS</div><dl class="stock-facts"><div><dt>Country</dt><dd>🇮🇳 India</dd></div><div><dt>Category</dt><dd>${e(s.sector||'Unclassified')}</dd></div><div><dt>India market-cap rank</dt><dd>${rank?'#'+rank:'—'}</dd></div><div><dt>Quote ticker</dt><dd>${e(stockTickerLabel(s))}</dd></div>${s.isin?`<div><dt>ISIN</dt><dd>${e(s.isin)}</dd></div>`:''}</dl>${s.exchangeListings?.length?`<div class="stock-listings"><small>Exchange listings</small>${s.exchangeListings.map(x=>`<span>${e(x.exchange)}: ${e(x.symbol)}</span>`).join('')}</div>`:''}${s.identitySource?`<p class="note">Former listing: ${(s.aliases||[]).filter(t=>/\.(NS|BO)$/.test(t)).map(escapeHtml).join(', ')} · <a class="source-link" href="${externalHref(s.identitySource)}" target="_blank" rel="noopener">Exchange change notice ↗</a></p>`:''}<div class="stock-data-status"><span class="dot"></span>${s.isin===null?'Current listing identity unverified · excluded from rankings':s.directoryOnly?'Directory verified · financials pending':feedMode==='live'?'Exchange quote data':'Reported financials'}</div></section><section class="card"><div class="eyebrow">FINANCIALS</div><dl class="stock-facts">${['earnings','margin','employees','assets','debt','cash'].map(k=>`<div><dt>${metrics[k]}</dt><dd>${amount(s[k],k)}</dd></div>`).join('')}</dl><p class="note">Financial fields may have different reporting and source-refresh dates.</p></section>${renderCompanyPeers(s)}<section class="stock-source-note"><span class="eyebrow">KNOW YOUR DATA</span><p>Missing values stay blank. Daily directory updates do not provide live prices or financial statements.</p><a class="source-link" href="#about">Data & methodology ↗</a></section></aside></div>`;
$('#stock-watch').onclick=()=>{watch.has(s.ticker)?watch.delete(s.ticker):watch.add(s.ticker);save('isv-watch',[...watch]);$('#watch-count').textContent=watch.size;$('#stock-watch').textContent=watch.has(s.ticker)?'★ Watching':'☆ Watchlist';$('#stock-watch').classList.toggle('selected',watch.has(s.ticker))};$('#stock-compare').onclick=()=>{if(!compare.includes(s.ticker)){if(compare.length>=4){toast('Choose up to four companies. Remove one in Compare first.');return}compare.push(s.ticker);save('isv-compare',compare)}location.hash='compare'};$('#stock-more').onchange=event=>{if(event.target.value){const target=companyURL(s,event.target.value);rememberRouteScroll(target);location.hash=target}};
renderCompanyMetric(s,key);if(!historyCache&&!historyRequest){historyRequest=fetch('company-history.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>{historyCache=data;historyRequest=null;const active=location.hash.split('/');if(active[1]===encodeURIComponent(s.ticker)&&active[2]==='cap')renderCompanyMetric(s,'cap')}).catch(()=>{historyCache={};historyRequest=null;if(location.hash===companyURL(s,'cap'))renderCompanyMetric(s,'cap')})}}
function renderCompanyPeers(s){const peers=stocks.filter(x=>x.ticker!==s.ticker&&x.cap!=null&&x.isin!==null&&(s.sector==='Unclassified'||x.sector===s.sector)).sort((a,b)=>b.cap-a.cap).slice(0,4);return peers.length?`<section class="card"><div class="eyebrow">${s.sector==='Unclassified'?'MARKET LEADERS':'IN THE SAME SECTOR'}</div><div class="stock-peers">${peers.map(x=>`<a href="${companyURL(x,'price')}">${logo(x)}<span>${escapeHtml(x.name)}<small>${escapeHtml(x.ticker)}</small></span><b>${amount(x.cap)}</b></a>`).join('')}</div></section>`:''}
function renderCompanyMetric(s,key){if(!$('#stock-main'))return;if(key==='reports'){renderCompanyReports(s);return}const [label,definition]=companyMetricDetails[key];const history=key==='cap'?historyCache?.[s.ticker]:null;const points=(history?.points||[]).filter(x=>Number.isFinite(x.year)&&Number.isFinite(x.value)).sort((a,b)=>a.year-b.year);const baseSource=s.source?sourceCompany(s,paths[key]||'marketcap'):null;
$('#stock-main').innerHTML=`<section class="card stock-chart-card"><div class="stock-metric-heading"><div><span class="eyebrow">${key==='cap'?'COMPANY VALUE':key==='price'?'MARKET PERFORMANCE':'FINANCIAL METRIC'}</span><h2>${label} of ${escapeHtml(s.name)}</h2></div><button id="stock-download" hidden title="Download available metric data">↓ CSV</button></div><div class="stock-current"><strong>${metricValue(s,key)}</strong><span>${key==='cap'?'Market capitalization':key==='price'?'Share price · loaded quote':'Available source value'}</span></div><p class="stock-definition">${definition}${key==='cap'&&companyRank(s)!=null?' '+escapeHtml(s.name)+' is ranked #'+companyRank(s)+' by market cap among the companies with financial data in our Indian universe.':''}</p>${points.length?`<div class="stock-chart-toolbar"><h3>Market cap history</h3>${chartTimelineControls('data-stock-range',companyRange,['1Y','5Y','MAX'])}</div><div id="stock-history-chart"></div><p class="note">Only 1Y, 5Y and MAX are supported by annual observations; shorter timelines need daily data. Annual source observations; 2026 is year to date. Historical values and current rankings can have different refresh times. INR history uses the current display FX rate, not historical exchange rates.</p>`:key==='price'?`${compareOverlay([s])}`:`<div class="stock-no-history"><span>▥</span><h3>${!historyCache&&key==='cap'?'Loading available history…':s[key]==null?'Data not available yet':'Historical series not connected'}</h3><p>${s[key]==null?'This company is included in Rankings. Financial values will appear when a verified source supplies them.':'The current source value is shown above. Zerodha supplies price and volume history; historical financial statements require a separate verified source.'}</p><a class="source-link" href="${companyURL(s,'price')}">View available price history →</a></div>`}${key==='price'?'<span class="note">Price history source: Zerodha Kite · NSE/BSE listing matched by ISIN.</span>':baseSource?`<a class="source-link" target="_blank" rel="noopener" href="${externalHref(baseSource)}">View company ${label.toLowerCase()} source ↗</a>`:`<a class="source-link" target="_blank" rel="noopener" href="https://upstox.com/developer/api-documentation/instruments/">Company directory source ↗</a>`}</section><div id="stock-history-table"></div><section class="card stock-related-metrics"><div class="stock-metric-heading"><h3>Explore ${escapeHtml(s.name)}’s financials</h3><span class="note">Available financial data</span></div><div class="stock-metric-grid">${['cap','revenue','earnings','pe','margin','dividend'].map(k=>`<a href="${companyURL(s,k)}"><small>${metrics[k]}</small><strong>${metricValue(s,k)}</strong><span>Explore →</span></a>`).join('')}</div></section>`;
if(key==='price'&&s.sparkline){bindRelativeOverlay([s]);document.querySelectorAll('[data-overlay-toggle]').forEach(b=>b.onclick=()=>{const visible=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',visible);document.querySelectorAll('[data-overlay]').forEach(line=>line.style.display=visible?'':'none')})}if(points.length){renderAnnualHistory(s,points);document.querySelectorAll('[data-stock-range]').forEach(button=>button.onclick=()=>{companyRange=button.dataset.stockRange;document.querySelectorAll('[data-stock-range]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',b===button)});renderAnnualHistory(s,points)})}$('#stock-download').onclick=()=>{const rows=points.length?[['Year','Market cap (USD billions)','Source'],...points.map(p=>[p.year,p.value,history.source])]:[['Company','Ticker','Metric','Value (source units)','Source'],[s.name,s.ticker,label,s[key]??'',baseSource||'Directory only']];const csv=rows.map(row=>row.map(csvCell).join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=s.ticker+'-'+key+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)} }
let annualChartObserver=null;
function renderAnnualHistory(s,allPoints){
 const controls=document.querySelector('.stock-chart-card .range-buttons');if(controls)document.querySelector('.stock-chart-toolbar').append(controls);const end=allPoints.at(-1).year,span=companyRange==='1Y'?2:companyRange==='5Y'?5:Infinity,points=allPoints.filter(p=>p.year>end-span);annualChartObserver?.disconnect();let annualDrawnWidth=0;
 function drawAnnual(){const holder=document.querySelector('#stock-history-chart');if(!holder)return;const width=Math.max(280,Math.round(holder.clientWidth||800)),height=width<500?285:320,left=width<500?70:85,right=18,top=24,bottom=height-40,displayValue=p=>p.value*1e9*(currency==='INR'?fx:1),scale=niceChartScale(points.map(displayValue),{includeZero:true}),x=p=>left+(p.year-points[0].year)/Math.max(1,points.at(-1).year-points[0].year)*(width-left-right),y=p=>bottom-(displayValue(p)-scale.min)/(scale.max-scale.min)*(bottom-top),line=points.map((p,i)=>(i?'L':'M')+x(p).toFixed(2)+','+y(p).toFixed(2)).join(' '),interval=Math.max(1,Math.ceil((points.length-1)/(width<500?2:5))),ticks=points.filter((p,i)=>i===0||i===points.length-1||i%interval===0&&points.length-1-i>=interval*.7);
 annualDrawnWidth=width;holder.innerHTML=`<svg class="annual-chart" data-source-as-of="${escapeHtml(historyCache?.[s.ticker]?.asOf||'')}" viewBox="0 0 ${width} ${height}" role="img" aria-label="Annual market capitalization of ${escapeHtml(s.name)} from ${points[0].year} to ${points.at(-1).year}"><text x="${left}" y="13">Market cap (${currency})</text>${scale.ticks.map(v=>{const yy=bottom-(v-scale.min)/(scale.max-scale.min)*(bottom-top);return `<line x1="${left}" x2="${width-right}" y1="${yy}" y2="${yy}" class="chart-gridline"/><text x="${left-10}" y="${yy+4}" text-anchor="end">${escapeHtml(currency==='INR'?formatINR(v):formatUSD(v))}</text>`}).join('')}<path d="${line}" class="annual-line" fill="none"/>${points.map(p=>`<circle cx="${x(p)}" cy="${y(p)}" r="3.5" class="annual-dot" aria-hidden="true"/>`).join('')}${ticks.map((p,i)=>`<text x="${x(p)}" y="${bottom+24}" text-anchor="${i===0?'start':i===ticks.length-1?'end':'middle'}">${p.year}</text>`).join('')}</svg>`;
 attachChartInteraction(holder.querySelector('svg'),[{name:s.name,color:document.body.classList.contains('dark')?'#7aaeff':'#3779ce',format:v=>amount(v),difference:(a,b)=>`${b-a>=0?'+':'−'}${amount(Math.abs(b-a))} (${a?((b-a)/a*100).toFixed(2):'—'}%)`,points:points.map(p=>({x:x(p),y:y(p),value:p.value,label:String(p.year)+(p.year===2026?' YTD':' year-end')}))}],{left,right:width-right,top,bottom});
 }
 drawAnnual();const target=document.querySelector('#stock-history-chart');annualChartObserver=new ResizeObserver(()=>{if(!target?.isConnected)annualChartObserver.disconnect();else if(Math.max(280,Math.round(target.clientWidth))!==annualDrawnWidth)drawAnnual()});if(target)annualChartObserver.observe(target);
$('#stock-history-table').innerHTML=`<section class="card stock-annual-table"><div class="stock-metric-heading"><h3>Market capitalization by year</h3><span class="coverage-chip">${companyRange==='MAX'?'All available years':companyRange}</span></div><div class="table-wrap"><table><thead><tr><th class="left">Year</th><th>Market cap</th><th>Annual change</th></tr></thead><tbody>${[...points].reverse().map(p=>`<tr><td class="left">${p.year}${p.year===2026?' <small class="coverage-chip">YTD</small>':''}</td><td class="number">${amount(p.value)}</td><td>${p.change==null?'—':changeBadge({change:p.change})}</td></tr>`).join('')}</tbody></table></div><p class="note">2026 compares the current source observation with year-end 2025; it is not a full-year return. Other values are reported year-end observations.</p></section>`}
function renderCompanyReports(s){const available=Boolean(s.source);$('#stock-main').innerHTML=`<section class="card"><span class="eyebrow">COMPANY DOCUMENTS</span><h2 style="margin-top:10px">Reports & corporate actions</h2><p class="stock-definition">Explore the available source documents and share history for ${escapeHtml(s.name)}.</p><div class="report-grid">${[['Annual reports','annual-reports','Financial statements and company reporting'],['ESG reports','esg-reports','Environmental, social and governance reporting'],['Sustainability reports','sustainability-reports','Sustainability disclosures'],['Dividend history','dividends','Company dividend distributions'],['Stock splits','stock-splits','Historical split events'],['Shares outstanding','shares-outstanding','Reported outstanding equity']].map(([title,path,description])=>`<article class="report-tile"><span class="report-icon">${path.includes('report')?'▤':'↗'}</span><h3>${title}</h3><p>${description}</p>${available?`<a class="source-link" href="${externalHref(sourceCompany(s,path))}" target="_blank" rel="noopener">Explore on source ↗</a>`:'<small class="note">No verified report source connected.</small>'}</article>`).join('')}</div><p class="note">Links open the source website. These documents and corporate-action histories are not stored locally.</p></section>`}
